package sieve

import (
	"reflect"
	"testing"
)

func TestSieveTo10(t *testing.T) {
	if got := Sieve(10); !reflect.DeepEqual(got, []int{2, 3, 5, 7}) {
		t.Errorf("Sieve(10) = %v, want [2 3 5 7]", got)
	}
}

func TestSieveTo20(t *testing.T) {
	want := []int{2, 3, 5, 7, 11, 13, 17, 19}
	if got := Sieve(20); !reflect.DeepEqual(got, want) {
		t.Errorf("Sieve(20) = %v, want %v", got, want)
	}
}

func TestSieveBelowTwo(t *testing.T) {
	if got := Sieve(1); len(got) != 0 {
		t.Errorf("Sieve(1) expected empty, got %v", got)
	}
}

func TestSieveTwo(t *testing.T) {
	if got := Sieve(2); !reflect.DeepEqual(got, []int{2}) {
		t.Errorf("Sieve(2) = %v, want [2]", got)
	}
}
